-- ================================================================================================
-- HappaTAS 3: persist/deflate (raw DEFLATE in pure Luau, the .tas body since 3.0.1): round trips of every
-- kind of data, matches at the window's edge, streams Python's zlib wrote (stored, fixed, dynamic blocks),
-- damaged streams (headless mock)
-- ================================================================================================
check(boot(3), "boots")
local Raw = __T3("persist/deflate")
-- (both yield every 64 KiB: run them in a thread the mock steps, like a save / load)
local function inThread(f, ...)
	local args, n = { ... }, select("#", ...)
	local res
	local co = coroutine.create(function() res = table.pack(pcall(f, table.unpack(args, 1, n))) end)
	coroutine.resume(co)
	local guard = 0
	while coroutine.status(co) ~= "dead" and guard < 100000 do
		M.step(1 / 60)
		guard = guard + 1
	end
	if not res.n or res[1] ~= true then error(res[2], 0) end
	return table.unpack(res, 2, res.n)
end
local Deflate = {
	compress = function(s) return inThread(Raw.compress, s) end,
	decompress = function(c, n) return inThread(Raw.decompress, c, n) end,
}

local function unhex(h) return (h:gsub("..", function(x) return string.char(tonumber(x, 16)) end)) end
local seed = 12345
local function rnd(n)
	seed = (seed * 1103515245 + 12345) % 2147483648
	return seed % n
end
local function roundTrip(name, s)
	local ok, c = pcall(Deflate.compress, s)
	if not ok then
		check(false, name .. ": compress errored: " .. tostring(c))
		return
	end
	local ok2, d = pcall(Deflate.decompress, c, #s)
	check(ok2 and d == s, name .. " (" .. #s .. " bytes -> " .. #c .. ")" .. (ok2 and "" or (": " .. tostring(d))))
	return c
end

section("round trips")
roundTrip("empty", "")
roundTrip("one byte", "x")
roundTrip("two bytes", "xy")
roundTrip("three equal", "aaa")
roundTrip("258 equal", string.rep("z", 258))
roundTrip("259 equal", string.rep("z", 259))
local zeros = roundTrip("100 000 zeros", string.rep("\0", 100000))
check(zeros ~= nil and #zeros < 300, "zeros pack small (" .. (zeros and #zeros or -1) .. ")")
local t = {}
for i = 1, 70000 do t[i] = string.char(rnd(256)) end
local noise = table.concat(t)
local nc = roundTrip("70 000 random bytes", noise)
check(nc ~= nil and #nc < 70000 * 1.01 + 64, "random bytes barely grow")
t = {}
for i = 1, 3000 do t[i] = string.format("%d,%.3f;", i, i * 0.016) end
roundTrip("text with numbers", table.concat(t))
-- the same 40 000-byte chunk twice, 32 768 bytes apart and more: matches right at the window's edge
local chunk = {}
for i = 1, 40000 do chunk[i] = string.char(rnd(256)) end
chunk = table.concat(chunk)
roundTrip("a repeat 40 000 bytes back (past the window)", chunk .. chunk)
roundTrip("a repeat exactly 32 768 bytes back", chunk:sub(1, 32768) .. chunk:sub(1, 300) .. chunk:sub(301, 32768))
-- a skewed alphabet: some symbols far rarer than others (long codes, cut to 15 bits)
t = {}
for i = 1, 200000 do
	local r = rnd(1000000)
	local c = 0
	while r < 1000000 / (2 ^ (c + 1)) and c < 25 do c = c + 1 end
	t[i] = string.char(65 + c)
end
local skew = roundTrip("Fibonacci-like symbol counts (length limit)", table.concat(t))
check(skew ~= nil, "a skewed alphabet packs")
-- frames-like data: small changing numbers in a fixed layout
t = {}
for i = 1, 20000 do t[i] = string.pack("<ddB", math.floor(i * 0.37) / 1000, 1.5, i % 3) end
local fr = table.concat(t)
local frc = roundTrip("frame-like rows", fr)
check(frc ~= nil and #frc < #fr / 4, "frame-like rows pack well")

section("streams Python's zlib wrote")
local ZLIB = {
	{ name = "stored blocks (level 0)", data = "", comp = "" },
	{ name = "fixed Huffman (short text, level 6)", data = "68656c6c6f2068656c6c6f2068656c6c6f20776f726c64", comp = "cb48cdc9c957c84022cbf38b725200" },
	{ name = "dynamic Huffman (level 9)", data = "", comp = "" },
}
for _, f in ipairs(ZLIB) do
	local data, comp = unhex(f.data), unhex(f.comp)
	local ok, d = pcall(Deflate.decompress, comp, #data)
	check(ok and d == data, f.name .. (ok and "" or (": " .. tostring(d))))
end

section("damaged streams error")
local good = Deflate.compress(fr)
check(not pcall(Deflate.decompress, good, #fr + 1), "a size one too big")
check(not pcall(Deflate.decompress, good, #fr - 1), "a size one too small")
check(not pcall(Deflate.decompress, good:sub(1, #good // 2), #fr), "a stream cut in half")
check(not pcall(Deflate.decompress, string.char(7) .. good:sub(2), #fr), "block type 3")
check(not pcall(Deflate.decompress, "", 5), "nothing at all")
-- every single flipped byte either errors or (rarely) still gives some output: it never hangs or crashes
local errs = 0
for i = 1, 40 do
	local k = 1 + rnd(#good)
	local bad = good:sub(1, k - 1) .. string.char((string.byte(good, k) + 1 + rnd(254)) % 256) .. good:sub(k + 1)
	local ok, d = pcall(Deflate.decompress, bad, #fr)
	if not ok then
		errs = errs + 1
		check(tostring(d):find("damaged", 1, true) ~= nil, "a damaged-file message (" .. tostring(d) .. ")")
	end
end
check(errs > 20, "most flipped bytes are caught (" .. errs .. " of 40)")
finish()
